const FINANCE_MILESTONE_STORAGE_KEY = 'ci_finance_milestones_seen_v1';

export interface FinanceMilestone {
  id: string;
  title: string;
  description: string;
  points?: number;
}

export function loadSeenFinanceMilestones(): Set<string> {
  if (typeof window === 'undefined') {
    return new Set();
  }
  try {
    const raw = window.localStorage.getItem(FINANCE_MILESTONE_STORAGE_KEY);
    if (!raw) return new Set();
    const parsed = JSON.parse(raw);
    return new Set(Array.isArray(parsed) ? parsed.filter((id) => typeof id === 'string') : []);
  } catch {
    return new Set();
  }
}

export function markFinanceMilestoneSeen(id: string): void {
  if (typeof window === 'undefined') {
    return;
  }
  const next = loadSeenFinanceMilestones();
  next.add(id);
  window.localStorage.setItem(FINANCE_MILESTONE_STORAGE_KEY, JSON.stringify(Array.from(next)));
}

export function detectNewFinanceMilestones(
  eligibleCount: number,
  options: Array<{ id: string; isEligible: boolean; title: string }>
): FinanceMilestone[] {
  const seen = loadSeenFinanceMilestones();
  const milestones: FinanceMilestone[] = [];

  if (eligibleCount > 0 && !seen.has('finance_eligible')) {
    milestones.push({
      id: 'finance_eligible',
      title: 'Finance options unlocked',
      description: `${eligibleCount} finance or incentive option${eligibleCount === 1 ? '' : 's'} match your emissions track record.`,
      points: 0,
    });
  }

  options.forEach((option) => {
    const key = `finance_option_${option.id}`;
    if (option.isEligible && !seen.has(key)) {
      milestones.push({
        id: key,
        title: `${option.title} — eligible`,
        description: 'You meet the criteria to explore this finance option.',
        points: 0,
      });
    }
  });

  return milestones;
}

